# Fetch detailed contents for all playlists in the library, and collect songs + their artists

passwords=apis.supervisor.show_account_passwords();
spotify_pw=next(p['password'] for p in passwords if p['account_name']=='spotify');
login=apis.spotify.login(username='ma_smith@gmail.com', password=spotify_pw);
access_token=login['access_token']

# Fetch playlists (public + private), looping pages

def fetch_playlists(is_public_val):
    all_ps=[]
    page_index=0
    page_limit=20
    while True:
        page=apis.spotify.show_playlist_library(access_token=access_token, page_index=page_index, page_limit=page_limit, is_public=is_public_val)
        if not page:
            break
        all_ps.extend(page)
        page_index += 1
    return all_ps

public_ps=fetch_playlists(True)
private_ps=fetch_playlists(False)

playlists={}
for p in public_ps+private_ps:
    playlists[p['playlist_id']]=p

print('playlists_total', len(playlists))
print('playlist_ids', sorted(playlists.keys()))

# For each playlist, fetch playlist details (songs)
all_song_ids=[]
song_artists_map={}  # song_id -> set of artist_ids
playlist_song_counts={}

for pid in sorted(playlists.keys()):
    pl=apis.spotify.show_playlist(playlist_id=pid, access_token=access_token)
    songs=pl.get('songs', [])
    playlist_song_counts[pid]=len(songs)
    print('playlist', pid, pl.get('title'), 'songs', len(songs))
    for s in songs:
        sid=s['id']
        all_song_ids.append(sid)
        if sid not in song_artists_map:
            song_artists_map[sid]=set()
        for a in s.get('artists', []):
            song_artists_map[sid].add(a['id'])

print('total_playlist_song_entries', len(all_song_ids))
print('unique_song_ids', len(set(all_song_ids)))
# Print a small sample of songs with artists
sample_sids=list(song_artists_map.keys())[:5]
for sid in sample_sids:
    print('sample_song', sid, 'artist_ids', sorted(song_artists_map[sid]))

